-- aria:billing-entry needs a per-line Invoice Number entry -- one order/SKU
-- line can be billed under its own invoice, distinct from the page's
-- separate whole-vehicle billing_entry.invoice_numbers tags field.
-- billing_order_details (V192/V253) has no column for it yet, and the
-- "Billing Table" grid (name billing_table) -- the one the billing officer
-- actually enters it on -- has no editable columns at all yet; it was a
-- purely server-computed display grid (see
-- BillingOrderDetailTransitionListener#writeBillingTableRateRows).
--
-- This migration does three things:
--   1. Adds billing_order_details.invoice_no (+ entity_field_registry row).
--   2. Adds an editable "Invoice No" column to billing_table, right after
--      SKU Name, and marks the grid localEditOnly (so typed edits stay
--      client-side until submit, matching every other editable ListView on
--      this page) plus adds it to the "Billing Done" button's
--      includeListData so those edits are actually submitted.
--   3. (Java side, not here) BillingOrderDetailTransitionListener reads the
--      submitted billing_table rows' invoice_no and folds it into the same
--      upsert as the rest of that grid's server-computed rate/tax figures.
--
-- Idempotent: guarded on billing_table's columns array still being its
-- pre-change length of 10 (11 once this has run).

ALTER TABLE billing_order_details
  ADD COLUMN IF NOT EXISTS invoice_no VARCHAR(64) NULL AFTER reason;

INSERT INTO entity_field_registry (tenant_id, entity_code, field_code, display_label, data_type, filterable, sortable, searchable, required, widget_kind)
SELECT -1, 'BillingOrderDetail', 'invoice_no', 'Invoice No', 'STRING', 1, 1, 1, 0, 'text'
WHERE NOT EXISTS (SELECT 1 FROM entity_field_registry WHERE entity_code = 'BillingOrderDetail' AND field_code = 'invoice_no');

UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '
